import { z } from 'zod';
export const ProvenanceSchema = z.object({
    source: z.string(),
    method: z.string().optional(),
    confidence: z.enum(['HIGH', 'MEDIUM', 'LOW', 'UNKNOWN']),
    freshnessSec: z.number().nonnegative(),
    licenseNote: z.string().optional(),
    isSimulated: z.boolean().default(false),
});
export const GeoEventSchema = z.object({
    id: z.string(),
    source: z.string(),
    timestamp: z.string(),
    latitude: z.number(),
    longitude: z.number(),
    altitude: z.number().optional(),
    type: z.string(),
    subtype: z.string().optional(),
    title: z.string(),
    description: z.string().optional(),
    confidence: z.enum(['HIGH', 'MEDIUM', 'LOW', 'UNKNOWN']),
    metadata: z.record(z.unknown()).optional(),
    provenance: ProvenanceSchema,
});
export const AircraftTrackSchema = z.object({
    id: z.string(),
    callsign: z.string(),
    aircraftType: z.string(),
    origin: z.string().optional(),
    destination: z.string().optional(),
    latitude: z.number(),
    longitude: z.number(),
    altitudeFeet: z.number(),
    heading: z.number(),
    velocityKnots: z.number(),
    squawk: z.string().optional(),
    timestamp: z.string(),
    provenance: ProvenanceSchema,
});
export const VesselTrackSchema = z.object({
    id: z.string(),
    vesselName: z.string(),
    mmsi: z.string(),
    imo: z.string().optional(),
    vesselType: z.string(),
    latitude: z.number(),
    longitude: z.number(),
    heading: z.number(),
    speedKnots: z.number(),
    destination: z.string().optional(),
    timestamp: z.string(),
    provenance: ProvenanceSchema,
});
export const SatelliteTrackSchema = z.object({
    noradId: z.number(),
    name: z.string(),
    category: z.string(),
    latitude: z.number(),
    longitude: z.number(),
    altitudeKm: z.number(),
    velocityKms: z.number(),
    tleLine1: z.string().optional(),
    tleLine2: z.string().optional(),
    nextPass: z.string().optional(),
    provenance: ProvenanceSchema,
});
export const GroundStationSchema = z.object({
    id: z.string(),
    name: z.string(),
    latitude: z.number(),
    longitude: z.number(),
    altitudeMeters: z.number(),
    status: z.enum(['ONLINE', 'OFFLINE', 'MAINTENANCE', 'DEGRADED']),
    antennaType: z.string(),
    telemetryLinkState: z.enum(['ACTIVE', 'IDLE', 'ERROR']),
    lastContact: z.string(),
});
export const WebsiteAssetSchema = z.object({
    domain: z.string(),
    ipAddresses: z.array(z.string()),
    serverHeader: z.string().optional(),
    technologies: z.array(z.string()),
    dnsRecords: z.record(z.array(z.string())),
    sslValid: z.boolean(),
    openPorts: z.array(z.number()),
    subdomains: z.array(z.string()),
    trackers: z.array(z.string()),
    scannedAt: z.string(),
    provenance: ProvenanceSchema,
});
export const IntelligenceItemSchema = z.object({
    id: z.string(),
    title: z.string(),
    source: z.string(),
    publicationTime: z.string(),
    category: z.string(),
    entities: z.array(z.string()),
    summary: z.string(),
    url: z.string().url().optional(),
    latitude: z.number().optional(),
    longitude: z.number().optional(),
    provenance: ProvenanceSchema,
});
export const SecurityFindingSchema = z.object({
    id: z.string(),
    target: z.string(),
    category: z.string(),
    severity: z.enum(['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO']),
    title: z.string(),
    evidence: z.string(),
    remediation: z.string(),
    authorizationContext: z.object({
        authorizedBy: z.string(),
        scope: z.string(),
        expiresAt: z.string(),
    }),
    timestamp: z.string(),
    provenance: ProvenanceSchema,
});
export const AgentTaskSchema = z.object({
    id: z.string(),
    parentTaskId: z.string().optional(),
    agentName: z.string(),
    objective: z.string(),
    status: z.enum(['PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'AWAITING_APPROVAL']),
    inputs: z.record(z.unknown()),
    outputs: z.record(z.unknown()).optional(),
    executionTrace: z.array(z.string()),
    createdAt: z.string(),
    completedAt: z.string().optional(),
});
